head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====

// 이미 존재하는 ID(tabs1) 로 addTab 을 호출하면 Confirm 창이 표시된다.
// Confirm 창에 실제로 출력된 텍스트를 결과창에 남기기 위해 호출 동안만 confirm 을 가로채 메시지를 수집하고 '확인'으로 응답한다.
scwin.btn_addTab_onclick = async function (e) {
    var objTab = $p.getComponentById("target1");
    var arrMsg = [];
    var fnOrigin = window.confirm;

    window.confirm = function (strMsg) {
        arrMsg.push(strMsg);
        return true;
    };

    try {
        await objTab.addTab("tabs1",
            {
                "label" : "newTabs",
                "title" : "dataObject",
                "closable" : "true"
            },
            {
                "src" : "",
                "frameMode" : "wframePreload",
                "scope" : true,
                "alwaysDraw" : true
            }
        );
    } finally {
        window.confirm = fnOrigin;
    }

    scwin.setReturnValue("[화면에 설정한 confirmMessage] confirmMessage");
    scwin.setReturnValue("[Confirm 창에 출력된 메시지] " + (arrMsg.length > 0 ? arrMsg[0] : "(Confirm 창 미표시)"));
    scwin.setReturnValue("[addTab 후 getTabCount()] " + objTab.getTabCount());
};
